(2,'Retardo menor','Retardo de 11 a 20 minutos','retardo','entrada','{\"campo\": \"minutos_retardo\", \"operador\": \"entre\", \"min\": 11, \"max\": 20}','{\"accion\": \"registrar\", \"clasificacion\": \"retardo_menor\", \"justificada\": false}',20,1,1,1,0,'2026-03-24 01:51:21',NULL,NULL),
